#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * @brief Generates a welcome message for the user with the specified username.
 * This message will be rendered in an HTML page after the user logs in.
 * The message format is "Welcome, <username>!".
 *
 * @param username The username of the user. Must not be NULL and should be a valid C string.
 * @return char* A dynamically allocated string containing the welcome message,
 * or NULL if memory allocation fails.
 */
char* get_welcome_message(const char* username) {
    // Check for invalid input
    if (username == NULL || *username == '\0') {
        return NULL;
    }

    // Calculate the required length including null terminator
    size_t static_part_length = strlen("Welcome, ");
    size_t username_length = strlen(username);
    size_t total_length = static_part_length + username_length + 1; // +1 for '!'

    // Allocate memory for the new string
    char* message = (char*) malloc(total_length * sizeof(char));

    // Check if memory allocation failed
    if (message == NULL) {
        return NULL;
    }

    // Safely construct the welcome message with bounds checking
    snprintf(message, total_length, "Welcome, %s!", username);

    return message;
}
```

